`,l.jsxs(s.li,{children:[l.jsx(s.em,{children:"Cuando llego, ella canta."}),' → "When I arrive, she sings."']}),`
`]}),`
`,l.jsxs(s.p,{children:["The aspect is doing real work here: the first sentence pastes the arrival ",l.jsx(s.em,{children:"into"}),' the singing. Translate it as "she sang", and you have invented a sequence that never happened — she was already singing when the arrival happened; the sentence tells you nothing about whether she stopped.']}),`
`,l.jsx(s.p,{children:"A second, uglier failure: habitual readings get flattened into one-off events."}),`
